   380	     * @param order   주문 정보
   381	     * @param payment 결제 정보
   382	     */
   383	    private void notifyUsersAndUpdateSaleStatus(Order order, Payment payment) {
   384	        try {
   385	            log.info("결제 관련 알림 및 판매 상태 업데이트 시작: 주문ID={}", order.getId());
   386	
   387	            // 1. OrderBid 조회
   388	            OrderBid orderBid = order.getOrderBid();
   389	            if (orderBid == null) {
   390	                // OrderBid가 없으면 SaleBid 탐색
   391	                SaleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
   392	                if (saleBid == null) {
   393	                    log.warn("주문에 연결된 판매 입찰 정보가 없습니다: 주문ID={}", order.getId());
   394	                    return;
   395	                }
   396	
   397	                Sale sale = saleBid.getSale();
   398	                if (sale == null) {
   399	                    log.warn("판매 입찰에 연결된 판매 정보가 없습니다: 판매입찰ID={}", saleBid.getId());
   400	                    return;
   401	                }
   402	
   403	                sendNotifications(order, sale); // 알림 전송
   404	                sale.updateStatus(SaleStatus.SOLD); // Sale 상태 변경
   405	                log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
   406	                return;
   407	            }
   408	
   409	            // 2. Sale 조회
   410	            Sale sale = orderBid.getSale();
   411	            if (sale == null) {
   412	                log.warn("주문 입찰에 연결된 판매 정보가 없습니다: 주문입찰ID={}", orderBid.getId());
   413	                return;
   414	            }
   415	
   416	            sendNotifications(order, sale); // 알림 전송
   417	
   418	            // 3. Sale 상태 변경
   419	            sale.updateStatus(SaleStatus.SOLD);
   420	            log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
   421	        } catch (Exception e) {
   422	            // 알림 및 상태 업데이트 실패 로깅만 하고 예외는 발생시키지 않음 (핵심 기능이 아니므로)
   423	            log.error("결제 관련 알림 및 판매 상태 업데이트 중 오류 발생: 주문ID={}, 오류={}",
   424	                    order.getId(), e.getMessage(), e);
   425	        }
   426	    }
