117	    private void validatePaymentRequest(Order order, User user, PaymentRequestDto requestDto) {
118	        if (order == null) {
119	            throw new PaymentException(PaymentErrorCode.PAYMENT_PROCESSING_FAILED, "주문 정보가 없습니다.");
120	        }
121	
122	        if (user == null) {
123	            throw new PaymentException(PaymentErrorCode.PAYMENT_PROCESSING_FAILED, "사용자 정보가 없습니다.");
124	        }
125	
126	        if (requestDto == null) {
127	            throw new PaymentException(PaymentErrorCode.PAYMENT_VALIDATION_FAILED, "결제 요청 정보가 없습니다.");
128	        }
129	
130	        // 주문 ID와 사용자 이메일이 일치하는지 확인
131	        if (!order.getId().equals(requestDto.getOrderId())) {
132	            throw new PaymentException(PaymentErrorCode.PAYMENT_VALIDATION_FAILED,
133	                    "주문 ID가 일치하지 않습니다. 요청ID: " + requestDto.getOrderId() + ", 실제ID: " + order.getId());
134	        }
135	
136	        if (!user.getEmail().equals(requestDto.getUserEmail())) {
137	            throw new PaymentException(PaymentErrorCode.PAYMENT_VALIDATION_FAILED,
138	                    "사용자 이메일이 일치하지 않습니다. 요청이메일: " + requestDto.getUserEmail() + ", 실제이메일: " + user.getEmail());
139	        }
140	
141	        // 결제 금액 검증
142	        if (requestDto.getPaidAmount() <= 0) {
143	            throw new PaymentException(PaymentErrorCode.INVALID_PAYMENT_AMOUNT,
144	                    "결제 금액은 0보다 커야 합니다. 금액: " + requestDto.getPaidAmount());
145	        }
146	    }
