    public void updateWarehouseStatus(Sale sale, WarehouseStatus newStatus) {
        try {
            // 입력 유효성 검사
            if (sale == null) {
                throw new WarehouseStorageProcessingFailedException("판매 정보가 없습니다.");
            }
            if (newStatus == null) {
                throw new InvalidWarehouseStatusException("새로운 상태 정보가 없습니다.");
            }

            WarehouseStorage storage = warehouseStorageQueryService.findBySale(sale);

            // 상태 전환 유효성 검사
            validateStatusTransition(storage.getStatus(), newStatus);

            storage.updateStatus(newStatus);
            warehouseStorageRepository.save(storage);
        } catch (Exception e) {
            if (e instanceof WarehouseStorageException) {
                throw e;
            }
            throw new WarehouseStorageProcessingFailedException("창고 보관 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }
    public void updateWarehouseStatusToSold(Sale sale) {
        if (sale == null) {
            throw new WarehouseStorageProcessingFailedException("판매 정보가 없습니다.");
        }

        if (sale.isWarehouseStorage()) {
            try {
                WarehouseStorage storage = warehouseStorageQueryService.findBySale(sale);

                // 이미 판매된 상품인지 확인
                if (storage.getStatus() == WarehouseStatus.SOLD) {
                    throw new InvalidStatusTransitionException("이미 판매 완료 상태인 상품입니다(ID: " + sale.getId() + ")");
                }

                // 상태 전환 유효성 검사
                validateStatusTransition(storage.getStatus(), WarehouseStatus.SOLD);

                storage.updateStatus(WarehouseStatus.SOLD);
                warehouseStorageRepository.save(storage);
            } catch (Exception e) {
                if (e instanceof WarehouseStorageException) {
                    throw e;
                }
                throw new WarehouseStorageProcessingFailedException("창고 보관 상태를 판매 완료로 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
            }
        }
    }
    public OrderShipment createOrderShipment(Order order, String receiverName, String receiverPhone,
                                             String postalCode, String address) {
        log.info("주문 배송 정보 생성 시작: orderId={}, receiverName={}",
                order.getId(), receiverName);

        OrderShipment shipment = OrderShipment.builder()
                .order(order)
                .receiverName(receiverName)
                .receiverPhone(receiverPhone)
                .postalCode(postalCode)
                .address(address)
                .status(ShipmentStatus.PENDING) // 초기 상태 설정
                .build();

        OrderShipment savedShipment = orderShipmentRepository.save(shipment);
        log.info("주문 배송 정보 생성 완료: shipmentId={}, orderId={}",
                savedShipment.getId(), order.getId());

        return savedShipment;
    }
    public OrderItem createOrderItem(Order order, ProductSize productSize, int price) {
        try {
            // 입력값 검증
            if (productSize == null) {
                throw new ProductSizeNotFoundException("상품 사이즈 정보가 없습니다.");
            }

            if (price <= 0) {
                throw new InvalidOrderDataException("주문 항목 가격은 0보다 커야 합니다. 현재 가격: " + price);
            }

            OrderItem orderItem = OrderItem.builder()
                    .order(order)
                    .productSize(productSize)
                    .quantity(1) // 주문 수량은 기본 1
                    .price(price)
                    .build();

            return orderItemRepository.save(orderItem);
        } catch (Exception e) {
            if (e instanceof ProductSizeNotFoundException || e instanceof InvalidOrderDataException) {
                throw e;
            }
            log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
            throw new OrderItemCreationFailedException("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }

